/*
 * A042433  Denominators of continued fraction convergents to sqrt(744).
 * https://oeis.org/A042433
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of n-th convergent of the continued fraction
 *            of sqrt(744)
 * Range:     u8 n <= 1, u16 n <= 12, u32 n <= 25, u64 n <= 49, u128 n <= 93,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by the standard recurrence for continued fraction convergents. */
seq_t a(idx_t n)
{
    /* Constants for sqrt(744) */
    const seq_t D   = (seq_t)744;
    const seq_t a0  = (seq_t)27;          /* floor(sqrt(744)) */

    /* Continued fraction variables */
    seq_t m   = (seq_t)0;
    seq_t d   = (seq_t)1;
    seq_t a_cur = a0;                     /* current partial quotient */

    /* Convergent denominator recurrence: Q_{-2}=1, Q_{-1}=0 */
    seq_t q_prev2 = (seq_t)1;              /* Q_{k-2} */
    seq_t q_prev1 = (seq_t)0;              /* Q_{k-1} */
    seq_t q_cur;

    /* Compute Q0 using a0 */
    q_cur = a_cur * q_prev1 + q_prev2;     /* Q0 = 1 */
    if (n == (idx_t)0) return q_cur;
    q_prev2 = q_prev1;                     /* shift for next */
    q_prev1 = q_cur;

    for (idx_t i = 1; i <= n; ++i)
    {
        /* next partial quotient a_{i} */
        seq_t m_next = d * a_cur - m;
        seq_t d_next = (D - m_next * m_next) / d;
        seq_t a_next = (a0 + m_next) / d_next;

        /* denominator Q_i */
        q_cur = a_next * q_prev1 + q_prev2;
        if (i == n) return q_cur;

        /* update for next iteration */
        m      = m_next;
        d      = d_next;
        a_cur  = a_next;
        q_prev2 = q_prev1;
        q_prev1 = q_cur;
    }
    return (seq_t)0;                      /* unreachable, but keeps compiler happy */
}
